const CACHE_NAME = 'app-portal-v1';
const STATIC_ASSETS = ['/'];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE_NAME).then((c) => c.addAll(STATIC_ASSETS)));
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))))
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  if (event.request.url.includes('/api/')) {
    event.respondWith(networkFirst(event.request));
  } else {
    event.respondWith(cacheFirst(event.request));
  }
});

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  try {
    const res = await fetch(request);
    if (res.ok) { const c = await caches.open(CACHE_NAME); c.put(request, res.clone()); }
    return res;
  } catch { return caches.match('/offline.html'); }
}

async function networkFirst(request) {
  try {
    const res = await fetch(request);
    if (res.ok) { const c = await caches.open(CACHE_NAME); c.put(request, res.clone()); }
    return res;
  } catch {
    const cached = await caches.match(request);
    return cached || new Response(JSON.stringify({ success: false, message: 'Offline' }), { status: 503 });
  }
}
